import type { JsonSchema } from "../casing/schemaKeyCasing";
import type { Overlay } from "../overlay/overlay";
import { typeExpression } from "./emitType";
import type { WirePathHints } from "./freeFormPaths";

const GENERATED_HEADER = `// Generated by @autumn/atmn-generator from packages/openapi/openapi-internal.yml.
// Do not edit — run \`bun generate\` in packages/atmn-generator instead.
`;

export type ClientRequestBody = {
	/** Emitted request type name, e.g. "CreateSandboxParams". */
	typeName: string;
	schema: JsonSchema;
	/** Where to stop recasing the REQUEST into wire casing. */
	hints: WirePathHints;
};

export type ClientOperation = {
	/** Method name on the client, e.g. "previewUpdate". */
	name: string;
	path: string;
	/** Emitted response type name, e.g. "PreviewUpdateCatalogResponse". */
	responseTypeName: string;
	responseSchema: JsonSchema;
	/** Where to stop recasing the RESPONSE back into fixture casing. */
	responseHints: WirePathHints;
	/**
	 * A body of its own, recased on the way out. Catalog operations omit it:
	 * their body is the already-wire-cased document `atmn()` returns.
	 */
	request?: ClientRequestBody;
};

/**
 * The client is generated for the same reason everything else is: v2 hand-rolled
 * fetchers and response schemas, which then drifted from the API they described.
 * Paths, response shapes and casing all come from the spec.
 */
const RUNTIME = `
export type ClientOptions = {
	/** Defaults to the production server in the spec. */
	baseUrl?: string;
	secretKey: string;
	fetch?: typeof globalThis.fetch;
};

export class AutumnApiError extends Error {
	readonly status: number;
	readonly body: unknown;

	constructor({
		status,
		body,
		path,
	}: {
		status: number;
		body: unknown;
		path: string;
	}) {
		// The server's message is the useful part; surfacing a bare status code
		// makes every failure look the same.
		const detail =
			typeof body === "object" && body !== null && "message" in body
				? String((body as { message: unknown }).message)
				: JSON.stringify(body);
		super(\`\${path} failed (\${status}): \${detail}\`);
		this.name = "AutumnApiError";
		this.status = status;
		this.body = body;
	}
}

const post = async ({
	options,
	path,
	body,
}: {
	options: ClientOptions;
	path: string;
	body: unknown;
}): Promise<unknown> => {
	const doFetch = options.fetch ?? globalThis.fetch;
	const response = await doFetch(\`\${options.baseUrl ?? DEFAULT_BASE_URL}\${path}\`, {
		method: "POST",
		headers: {
			authorization: \`Bearer \${options.secretKey}\`,
			"content-type": "application/json",
		},
		body: JSON.stringify(body),
	});

	const text = await response.text();
	const parsed = text ? JSON.parse(text) : null;
	if (!response.ok) {
		throw new AutumnApiError({ status: response.status, body: parsed, path });
	}
	return parsed;
};
`;

const hintsLiteral = ({
	name,
	hints,
}: {
	name: string;
	hints: WirePathHints;
}): string =>
	`const ${name} = hintsOf({
	recordPaths: ${JSON.stringify(hints.recordPaths)},
	frozenPaths: ${JSON.stringify(hints.frozenPaths)},
});`;

const hintsName = ({
	operation,
	kind,
}: {
	operation: ClientOperation;
	kind: "REQUEST" | "RESPONSE";
}): string => `${operation.name.toUpperCase()}_${kind}_HINTS`;

const operationMethod = ({
	operation,
}: {
	operation: ClientOperation;
}): string => {
	const bodyType = operation.request?.typeName ?? "WireDocument";
	const sentBody =
		operation.request === undefined
			? "body"
			: `toWire({ value: body, path: "", hints: ${hintsName({ operation, kind: "REQUEST" })} })`;
	return `	${operation.name}: async (
		body: ${bodyType},
	): Promise<${operation.responseTypeName}> =>
		toFixture({
			value: await post({ options, path: "${operation.path}", body: ${sentBody} }),
			path: "",
			hints: ${hintsName({ operation, kind: "RESPONSE" })},
		}) as ${operation.responseTypeName},`;
};

/** Only what the emitted methods actually reference, so the output stays lint-clean. */
const wireImport = ({
	operations,
}: {
	operations: ClientOperation[];
}): string => {
	const names = ["hintsOf", "toFixture"];
	if (operations.some((operation) => operation.request !== undefined))
		names.push("toWire");
	if (operations.some((operation) => operation.request === undefined))
		names.push("type WireDocument");
	return `import { ${names.join(", ")} } from "./wire";`;
};

export const emitClientModule = ({
	baseUrl,
	operations,
	overlay,
}: {
	baseUrl: string;
	operations: ClientOperation[];
	overlay: Overlay;
}): string =>
	[
		GENERATED_HEADER,
		wireImport({ operations }),
		`\nconst DEFAULT_BASE_URL = ${JSON.stringify(baseUrl)};`,
		RUNTIME,
		...operations.flatMap((operation) =>
			operation.request === undefined
				? []
				: [
						`export type ${operation.request.typeName} = ${typeExpression({
							schema: operation.request.schema,
							path: "",
							context: { overlay, collection: operation.name },
						})};`,
					],
		),
		...operations.map(
			(operation) =>
				`export type ${operation.responseTypeName} = ${typeExpression({
					schema: operation.responseSchema,
					path: "",
					context: { overlay, collection: operation.name },
				})};`,
		),
		...operations.flatMap((operation) =>
			operation.request === undefined
				? []
				: [
						hintsLiteral({
							name: hintsName({ operation, kind: "REQUEST" }),
							hints: operation.request.hints,
						}),
					],
		),
		...operations.map((operation) =>
			hintsLiteral({
				name: hintsName({ operation, kind: "RESPONSE" }),
				hints: operation.responseHints,
			}),
		),
		`
export const createClient = (options: ClientOptions) => ({
${operations.map((operation) => operationMethod({ operation })).join("\n")}
});

export type AutumnClient = ReturnType<typeof createClient>;
`,
	].join("\n");
